import { useState, useCallback } from 'react';
import { useNavigate } from 'react-router-dom';
import { DashboardShell } from '../components/layout/DashboardShell';
import { Header } from '../components/layout/Header';
import { WizardLayout } from '../components/wizard/WizardLayout';
import { FormField } from '../components/wizard/FormField';
import { ModeSelector } from '../components/wizard/ModeSelector';
import { FileUploadZone } from '../components/wizard/FileUploadZone';
import { CodePreview } from '../components/wizard/CodePreview';
import { ValidationBanner } from '../components/wizard/ValidationBanner';
import { useWizardStore } from '../stores/wizard-store';
import { generateRanktable, validateRanktable, saveFile } from '../api/simulation-api';

const MODE_OPTIONS = [
  { value: 'auto' as const, label: 'Auto Generate', description: 'Generate from GPU count and rack size' },
  { value: 'custom' as const, label: 'Custom Topology', description: 'Define rack-to-rank mapping manually' },
  { value: 'upload' as const, label: 'Upload File', description: 'Upload an existing ranktable.json' },
];

export function RankTablePage() {
  const navigate = useNavigate();
  const {
    ranktableMode, setRanktableMode,
    ranktableConfig, setRanktableConfig,
    ranktableData, setRanktableData,
    setRanktableSaved, setRanktableSavedPath,
  } = useWizardStore();

  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [successMsg, setSuccessMsg] = useState<string | null>(null);
  const [validationErrors, setValidationErrors] = useState<readonly string[]>([]);

  const handleConfigChange = useCallback(
    (field: string, value: string | number) => {
      setRanktableConfig({ ...ranktableConfig, [field]: value });
    },
    [ranktableConfig, setRanktableConfig],
  );

  const handleNext = useCallback(async () => {
    setIsLoading(true);
    setError(null);
    setValidationErrors([]);
    setSuccessMsg(null);
    try {
      // Generate if needed (auto/custom mode)
      let data = ranktableData;
      if (ranktableMode === 'auto' || ranktableMode === 'custom') {
        if (!data) {
          const result = await generateRanktable(ranktableConfig);
          data = result.ranktable;
          setRanktableData(result.ranktable, result.rank_rack_map);
        }
        // Validate
        const validation = await validateRanktable(data);
        if (!validation.valid) {
          setValidationErrors(validation.errors);
        }
      }

      if (!data) {
        setError('请先生成或上传 RankTable');
        return;
      }

      const result = await saveFile('ranktable.json', JSON.stringify(data, null, 2));
      setRanktableSaved(true);
      setRanktableSavedPath(result.path);
      navigate('/deploy/launch');
    } catch (err) {
      setError(err instanceof Error ? err.message : '操作失败');
    } finally {
      setIsLoading(false);
    }
  }, [ranktableMode, ranktableConfig, ranktableData, setRanktableData, setRanktableSaved, setRanktableSavedPath]);

  const handleFileUpload = useCallback(
    (content: string) => {
      try {
        const parsed = JSON.parse(content);
        setRanktableData(parsed, {});
      } catch {
        setError('Invalid JSON file');
      }
    },
    [setRanktableData],
  );

  const previewContent = ranktableData ? JSON.stringify(ranktableData, null, 2) : '';

  return (
    <DashboardShell>
      <Header title="RankTable 配置" backLink="/" />

      <WizardLayout
        title="RankTable 配置"
        description="生成 RankTable，将 GPU Rank 映射到物理机架"
        showDeployStepper
        actions={
          <button
            type="button"
            onClick={handleNext}
            disabled={isLoading}
            className="px-6 py-2 rounded-lg bg-[var(--color-accent-blue)] text-white text-sm font-medium hover:opacity-90 disabled:opacity-50 transition-opacity"
          >
            {isLoading ? '处理中...' : '下一步 →'}
          </button>
        }
      >
        {error && <ValidationBanner type="error" message={error} />}
        {successMsg && <ValidationBanner type="success" message={successMsg} />}
        {validationErrors.length > 0 && (
          <ValidationBanner type="warning" message="校验警告" details={validationErrors} />
        )}

        <div className="space-y-6">
          <ModeSelector value={ranktableMode} onChange={setRanktableMode} options={MODE_OPTIONS} />

          {ranktableMode === 'auto' && (
            <div className="grid grid-cols-2 gap-4">
              <FormField label="Total Ranks (GPUs)">
                <input
                  type="number"
                  min={1}
                  value={ranktableConfig.rank_count}
                  onChange={(e) => handleConfigChange('rank_count', parseInt(e.target.value) || 1)}
                  className="w-full px-3 py-2 rounded-lg bg-[var(--color-bg-primary)] border border-[var(--color-bg-hover)] text-[var(--color-text-primary)] text-sm"
                />
              </FormField>

              <FormField label="GPUs per Rack">
                <input
                  type="number"
                  min={1}
                  value={ranktableConfig.gpus_per_rack}
                  onChange={(e) => handleConfigChange('gpus_per_rack', parseInt(e.target.value) || 1)}
                  className="w-full px-3 py-2 rounded-lg bg-[var(--color-bg-primary)] border border-[var(--color-bg-hover)] text-[var(--color-text-primary)] text-sm"
                />
              </FormField>

              <FormField label="Rack Prefix" hint="Naming prefix for racks">
                <input
                  type="text"
                  value={ranktableConfig.superpod_prefix}
                  onChange={(e) => handleConfigChange('superpod_prefix', e.target.value)}
                  className="w-full px-3 py-2 rounded-lg bg-[var(--color-bg-primary)] border border-[var(--color-bg-hover)] text-[var(--color-text-primary)] text-sm"
                />
              </FormField>

              <FormField label="Computed Racks">
                <div className="px-3 py-2 rounded-lg bg-[var(--color-bg-tertiary)] text-[var(--color-text-secondary)] text-sm">
                  {Math.ceil(ranktableConfig.rank_count / ranktableConfig.gpus_per_rack)} racks
                </div>
              </FormField>
            </div>
          )}

          {ranktableMode === 'upload' && (
            <FileUploadZone
              accept=".json"
              label="Drop a ranktable.json file here or click to upload"
              onFileContent={handleFileUpload}
            />
          )}

          {previewContent && (
            <CodePreview content={previewContent} maxHeight="300px" />
          )}
        </div>
      </WizardLayout>
    </DashboardShell>
  );
}
